/**
 * Deploy-time configuration for the Supabase backend.
 *
 * You normally do NOT edit this file. The deploy workflow
 * (.github/workflows/deploy.yml) builds the website with your values
 * from GitHub → Settings → Secrets and variables → Actions → Variables:
 *
 * - VITE_SUPABASE_URL: made from the variable SUPABASE_PROJECT_REF
 *   (https://<project-ref>.supabase.co). Not a secret.
 * - VITE_SUPABASE_PUBLISHABLE_KEY: the variable SUPABASE_PUBLISHABLE_KEY,
 *   the project's publishable key (Supabase → Project Settings → API
 *   Keys). It is publishable BY DESIGN: Supabase client apps embed it,
 *   and row-level security (supabase/migrations) is what actually
 *   protects the company's rows.
 * - VITE_TURNSTILE_SITE_KEY: the variable TURNSTILE_SITE_KEY (optional),
 *   the Cloudflare Turnstile SITE key for the booking form and the login
 *   screen. The matching SECRET key is the GitHub secret
 *   TURNSTILE_SECRET_KEY; the deploy hands it to Supabase.
 *
 * Until the URL and key are set (for example on your own computer with
 * `npm run dev`), the app uses the local demo adapter (see
 * src/data/selectAdapter.ts) and runs entirely in the browser with no
 * data saved anywhere. For a local Supabase, put the values in a
 * `.env.local` file (it is not committed):
 *   VITE_SUPABASE_URL=http://127.0.0.1:54321
 *   VITE_SUPABASE_PUBLISHABLE_KEY=<from `npx supabase status`>
 *
 * - companyId: the id of this business's one company row. It must equal
 *   public.app_config.company_id in the database; the baseline migration
 *   creates the company with exactly this id. Do not change it.
 *
 * NEVER put the service_role / secret key here (or anywhere in this
 * codebase). It bypasses row-level security entirely and belongs only in
 * trusted server-side code, which this browser app does not have.
 */
const env = import.meta.env as Record<string, string | undefined>;

export const supabaseConfig = {
  url: (env.VITE_SUPABASE_URL ?? "").trim() || "PLACEHOLDER",
  anonKey: (env.VITE_SUPABASE_PUBLISHABLE_KEY ?? "").trim() || "PLACEHOLDER",
  companyId: "11111111-1111-4111-8111-111111111111",
  turnstileSiteKey: (env.VITE_TURNSTILE_SITE_KEY ?? "").trim() || "PLACEHOLDER",
};

/** True once a real Turnstile site key is set. */
export const turnstileConfigured =
  supabaseConfig.turnstileSiteKey !== "PLACEHOLDER" &&
  supabaseConfig.turnstileSiteKey !== "";

/** True only once a real project URL and anon key are set. */
export const supabaseConfigured =
  supabaseConfig.url !== "PLACEHOLDER" &&
  supabaseConfig.url !== "" &&
  supabaseConfig.anonKey !== "PLACEHOLDER" &&
  supabaseConfig.anonKey !== "";
